'use strict';
import headerImageWatch from '../images/slider/header-watch.png';
import headerImageElectronics from '../images/slider/header-electronics.png';
import headerImageGrass from '../images/slider/header-grass.png';

const page = document.querySelector('body');
const header = page.querySelector('header');
const rightArrow = header.querySelector('.right-arrow');
const leftArrow = header.querySelector('.left-arrow');

const images = [
  `url(${headerImageWatch})`,
  `url(${headerImageElectronics})`,
  `url(${headerImageGrass})`,
];

let currentImageIndex = 0;

rightArrow.addEventListener('click', () => {
  const sliderSection = header.querySelector('.header__slider-section');
  console.log('Натискання на rightArrow'); // Перевірка, чи виконується подія

  currentImageIndex = (currentImageIndex + 1) % images.length;

  sliderSection.style.backgroundImage = images[currentImageIndex];

});

leftArrow.addEventListener('click', () => {
  const sliderSection = header.querySelector('.header__slider-section');
  console.log('Натискання на leftArrow'); // Перевірка, чи виконується подія

  currentImageIndex = (currentImageIndex - 1);
  if (currentImageIndex < 0) {
    currentImageIndex = 2;
  }

  sliderSection.style.backgroundImage = images[currentImageIndex];

});

setInterval(() => {
  const sliderSection = header.querySelector('.header__slider-section');

  currentImageIndex = (currentImageIndex + 1) % images.length;

  sliderSection.style.backgroundImage = images[currentImageIndex];
}, 3000);
